<?php require 'includes/boot.php';need();$d=db();$sc=admin()?'':' WHERE department_id='.(int)user()['department_id'];$an=$sc?$sc.' AND':' WHERE';$paperScope=$sc;if(user()['role']==='teacher')$paperScope.=($paperScope?' AND ':' WHERE ').'created_by='.(int)user()['id'];
$c=fn($t,$w='')=>$d->query("SELECT COUNT(*) FROM $t $w")->fetchColumn();
$cards=[['Departments',$c('departments',admin()?'':'WHERE id='.(int)user()['department_id']),'building'],['Department Admins',$c('users',$an.' role="dept_admin"'),'person-gear'],['Batches',$c('batches',$sc),'collection'],['Semesters',$c('classes',$sc),'diagram-3'],['Subjects',$c('subjects',$sc),'book'],['Teachers',$c('users',$an.' role="teacher"'),'people'],['Papers',$c('question_papers',$paperScope),'file-earmark-text'],['Drafts',$c('question_papers',($paperScope?$paperScope.' AND':' WHERE').' status="draft"'),'pencil'],['Finalized',$c('question_papers',($paperScope?$paperScope.' AND':' WHERE').' status="final"'),'patch-check']];
$paperWhere=admin()?'':" WHERE p.department_id=".(int)user()['department_id'].(user()['role']==='teacher'?' AND p.created_by='.(int)user()['id']:'');
$rec=$d->query("SELECT p.*,s.name sn,b.name batch_name FROM question_papers p JOIN subjects s ON s.id=p.subject_id LEFT JOIN batches b ON b.id=p.batch_id".$paperWhere." ORDER BY p.updated_at DESC LIMIT 6")->fetchAll();
$overview=admin()?$d->query('SELECT d.id,d.name,GROUP_CONCAT(DISTINCT a.label ORDER BY a.id SEPARATOR ", ") years,COUNT(DISTINCT c.id) semesters,COUNT(DISTINCT s.id) subjects,COUNT(DISTINCT CASE WHEN u.role="dept_admin" THEN u.id END) admins,COUNT(DISTINCT CASE WHEN u.role="teacher" THEN u.id END) teachers FROM departments d LEFT JOIN academic_years a ON a.department_id=d.id LEFT JOIN classes c ON c.department_id=d.id LEFT JOIN subjects s ON s.department_id=d.id LEFT JOIN users u ON u.department_id=d.id GROUP BY d.id ORDER BY d.name')->fetchAll():[];
head('Dashboard');?>
<div class=row g-3><?php foreach($cards as $i=>$k):?><div class="col-6 col-lg-3 mb-3"><div class=cardx style="animation-delay:<?=$i*.08?>s"><div class=stat><i class="bi bi-<?=$k[2]?>"></i><div><b><?=$k[1]?></b><small class=text-muted><?=$k[0]?></small></div></div></div></div><?php endforeach?></div>
<div class="mb-3"><a class="btn btn-q" href=paper_form.php>+ Create New Paper</a> <?php if(user()['role']==='teacher'):?><a class="btn btn-q" href=marks.php>Student Marks</a><?php endif?> <?php if(user()['role']!=='teacher'):?><a class="btn btn-q" href="manage.php?t=batches">Manage Batches</a><a class="btn btn-q" href="manage.php?t=subjects">Manage Subjects</a><a class="btn btn-q" href="manage.php?t=users">Manage Teachers</a><?php endif?> <?php if(admin()):?><a class="btn btn-q" href="manage.php?t=departments">Manage Departments</a><a class="btn btn-q" href="manage.php?t=department_admins">Manage Department Admins</a><?php endif?></div>
<?php if(admin()):?><div class="cardx mb-3"><h6>Departments and academic structure</h6><div class=table-responsive><table class=t><tr><th>Department<th>Academic years<th>Semesters<th>Subjects<th>Department Admins<th>Teachers</tr><?php foreach($overview as$r):?><tr><td><?=e($r['name'])?><td><?=e($r['years']?:'Not configured')?><td><?=e($r['semesters'])?><td><?=e($r['subjects'])?><td><?=e($r['admins'])?><td><?=e($r['teachers'])?></tr><?php endforeach;if(!$overview):?><tr><td colspan=6 class=text-muted>No departments yet.</td></tr><?php endif?></table></div></div><?php endif?>
<div class=cardx><h6>Recently updated papers</h6><div class=table-responsive><table class=t><tr><th>Subject<th>Batch<th>Type<th>Marks<th>Status<th>Updated</tr><?php foreach($rec as $r):?><tr><td><a href="papers.php?subject_id=<?=$r['subject_id']?>"><?=e($r['sn'])?></a><td><?=e($r['batch_name']?:'—')?><td><?=e($r['exam_type'])?><td><?=$r['total_marks']?><td><?=e($r['status'])?><td><?=$r['updated_at']?></tr><?php endforeach;if(!$rec)echo '<tr><td colspan=6 class=text-muted>No papers yet.</tr>'?></table></div></div>
<?php foot();
